a('I87.0', [('I87.0', 'code de la Classification internationale des maladies, 10e révision, modification allemande')], 'Syndrome post-phlébitique', '<p>Code CIM-10-GM 2024.</p>', 'i83-codage')
a('I87.00', [('I87.00', 'code de la Classification internationale des maladies, 10e révision, modification allemande')], 'Syndrome post-thrombotique sans ulcération', '<p>Code CIM-10-GM 2024.</p>', 'i83-codage')
a('I87.01', [('I87.01', 'code de la Classification internationale des maladies, 10e révision, modification allemande')], 'Syndrome post-thrombotique avec ulcération', '<p>Code CIM-10-GM 2024.</p>', 'i83-codage')
a('I87.1', [('I87.1', 'code de la Classification internationale des maladies, 10e révision, modification allemande')], 'Compression veineuse', '<p>Code CIM-10-GM 2024.</p>', 'i83-codage')
a('I87.2', [('I87.2', 'code de la Classification internationale des maladies, 10e révision, modification allemande')], 'Insuffisance veineuse (chronique) (périphérique)', '<p>Code CIM-10-GM 2024.</p>', 'i83-codage')
a('I87.20', [('I87.20', 'code de la Classification internationale des maladies, 10e révision, modification allemande')], 'Insuffisance veineuse (chronique) (périphérique) sans ulcération', '<p>Code CIM-10-GM 2024.</p>', 'i83-codage')
a('I87.21', [('I87.21', 'code de la Classification internationale des maladies, 10e révision, modification allemande')], 'Insuffisance veineuse (chronique) (périphérique) avec ulcération', '<p>Code CIM-10-GM 2024.</p>', 'i83-codage')
a('I87.8', [('I87.8', 'code de la Classification internationale des maladies, 10e révision, modification allemande')], 'Autres atteintes veineuses précisées', '<p>Code CIM-10-GM 2024.</p>', 'i83-codage')
a('I87.9', [('I87.9', 'code de la Classification internationale des maladies, 10e révision, modification allemande')], 'Atteinte veineuse, sans précision', '<p>Code CIM-10-GM 2024.</p>', 'i83-codage')
a('PIK3CA', [('PI', 'PhosphatidylInositol (phosphatidylinositol)'), ('K', 'Kinase'), ('3', '3 (phosphorylation en position 3 de l’inositol)'), ('CA', 'Catalytic subunit Alpha (sous-unité catalytique alpha)')], 'Gène de la sous-unité catalytique alpha de la phosphatidylinositol-4,5-bisphosphate 3-kinase', '<p>Gène d’une enzyme de signalisation qui stimule la croissance et la prolifération cellulaires. Des variants activateurs apparus pendant le développement, présents seulement dans une partie des cellules du tissu atteint (mosaïque somatique), causent la plupart des syndromes de Klippel-Trénaunay et d’autres malformations vasculaires avec hypertrophie (Luks et al., J Pediatr 2015). Ils se recherchent dans le tissu malformé et non dans le sang.</p>', 'i83-gen')
